let personagensAtuais = [];

function criarCards(lista){

    personagensAtuais = lista;

    const resultado =
    document.getElementById("resultado");

    resultado.innerHTML = "";

    lista.forEach((personagem, index) => {

        resultado.innerHTML += `
        <div class="personagem" onclick="abrirDetalhes(${index})">

            <img
            src="${personagem.imagem}"
            alt="${personagem.nome}">

            <h3>${personagem.nome}</h3>

            <p>${personagem.descricao}</p>

        </div>
        `;

    });

}

function abrirDetalhes(index){

    const personagem =
    personagensAtuais[index];

    const modal =
    document.getElementById("modal");

    document.getElementById("detalheImagem").src =
    personagem.imagem;

    document.getElementById("detalheNome").textContent =
    personagem.nome;

    document.getElementById("detalheDescricao").textContent =
    personagem.descricao;

    document.getElementById("detalheExtra").textContent =
    personagem.extra;

    document.getElementById("detalheApelido").textContent =
    personagem.apelido || "Não informado";

    document.getElementById("detalheIdade").textContent =
    personagem.idade || "Não informado";

    document.getElementById("detalheAltura").textContent =
    personagem.altura || "Não informado";

    document.getElementById("detalheTime").textContent =
    personagem.time || "Não informado";

    document.getElementById("detalheArma").textContent =
    personagem.arma || "Não informado";

    document.getElementById("extraInfo")
    .classList.add("escondido");

    modal.classList.remove("escondido");

    document.body.style.overflow = "hidden";
}

function fecharModal(){

    document.getElementById("modal")
    .classList.add("escondido");

    document.body.style.overflow = "auto";
}

function mostrarExtra(){

    document.getElementById("extraInfo")
    .classList.toggle("escondido");
}

window.onclick = function(event){

    const modal =
    document.getElementById("modal");

    if(event.target === modal){

        fecharModal();
    }
};

document.addEventListener("keydown", function(event){

    if(event.key === "Escape"){

        fecharModal();
    }
});
